namespace App\Filament\Widgets;

use Illuminate\Database\Query\Builder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

/**
 * Shared query compiler for report widgets (Fixzy SysMaker generated
 * code). Applies the compiled filter config: one basic filter, a
 * timeframe on created_at, and advanced rule groups from the
 * Dashboard Builder's Query Builder.
 *
 * Safety: identifiers are validated against the live schema (and a
 * strict regex) before being interpolated; values always go through
 * query bindings. Advanced rules that reference a *different* table
 * than the widget's source table are skipped (no join context).
 */
class ReportQuery
{
    /**
     * Apply the report's safe filters to an Eloquent query builder.
     *
     * @param  Builder  $query  Query builder to modify.
     * @param  array  $cfg  Report configuration array.
     */
    public static function apply(Builder $query, array $cfg): void
    {
        $table = $cfg['table'] ?? '';

        // Basic filter.
        $ff = $cfg['filter_field'] ?? '';
        if ($ff !== '' && self::safeIdent($ff) && Schema::hasColumn($table, $ff)) {
            $op = $cfg['filter_operator'] ?? '=';
            $val = $cfg['filter_value'] ?? '';
            if ($op === 'LIKE') {
                $query->where($ff, 'LIKE', "%{$val}%");
            } else {
                $query->where($ff, $op, $val);
            }
        }

        // Timeframe on created_at (only when the column exists).
        $tf = $cfg['timeframe'] ?? 'all';
        if ($tf !== 'all' && Schema::hasColumn($table, 'created_at')) {
            $now = now();
            $range = match ($tf) {
                'today' => [$now->copy()->startOfDay(), $now->copy()->endOfDay()],
                'this_month' => [$now->copy()->startOfMonth(), $now->copy()->endOfMonth()],
                'this_year' => [$now->copy()->startOfYear(), $now->copy()->endOfYear()],
                default => null,
            };
            if ($range) {
                $query->whereBetween('created_at', $range);
            }
        }

        // Advanced rule groups from the Query Builder.
        $adv = $cfg['advanced'] ?? null;
        if (is_array($adv)) {
            self::applyRuleGroup($query, $adv, $table);
        }
    }

    private static function applyRuleGroup(Builder $query, array $group, string $table): void
    {
        $logic = strtoupper($group['logic'] ?? 'AND') === 'OR' ? 'orWhere' : 'where';
        $rules = $group['rules'] ?? [];
        if (! is_array($rules) || count($rules) === 0) {
            return;
        }

        $query->where(function (Builder $q) use ($rules, $table, $logic) {
            foreach ($rules as $rule) {
                if (($rule['type'] ?? '') === 'group') {
                    $q->{$logic}(function (Builder $sub) use ($rule, $table) {
                        self::applyRuleGroup($sub, $rule, $table);
                    });
                    continue;
                }
                $ruleTable = $rule['table'] ?? $table;
                if ($ruleTable !== $table) {
                    continue; // cross-table rule: no join context, skip
                }
                $field = $rule['field'] ?? '';
                $op = $rule['operator'] ?? '=';
                $val = $rule['value'] ?? '';
                if (! self::safeIdent($field) || ! Schema::hasColumn($table, $field)) {
                    continue;
                }
                if (! in_array($op, ['=', '!=', '>', '<', '>=', '<=', 'LIKE'], true)) {
                    continue;
                }
                if ($op === 'LIKE') {
                    $q->{$logic}($field, 'LIKE', "%{$val}%");
                } else {
                    $q->{$logic}($field, $op, $val);
                }
            }
        });
    }

    private static function safeIdent(string $id): bool
    {
        return (bool) preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/', $id);
    }
}
